from pathlib import Path
p=Path('/mnt/data/atlas_pilot'); f=p/'app.js';s=f.read_text()
needle='function openExerciseDetail(name){'
insert='''const ATLAS_PILOT = {
  'Pec Deck': {art:'pec-deck', cues:['Adjust the seat so handles align near mid-chest.','Keep your back supported and feet planted.','Bring the handles together smoothly; avoid shrugging.','Return slowly within a comfortable range.'],positions:['Start: seated, chest up, arms open.','Finish: seated, handles together in front of chest.']},
  'Barbell Bench Press': {art:'barbell-bench-press', cues:['Lie on a flat bench with feet planted.','Set your shoulder blades firmly against the bench.','Lower the bar with control toward the chest.','Press upward while staying supported on the bench.'],positions:['Start: lying on the flat bench, bar near chest.','Finish: still lying on the flat bench, arms extended.']},
  'Barbell Back Squat': {art:'barbell-back-squat', cues:['Place the bar securely across your upper back.','Start upright with feet about shoulder width.','Brace and descend under control to a comfortable depth.','Stand by driving through the whole foot.'],positions:['Start: standing upright, bar across upper back.','Finish illustration: bottom of squat, bar remains on upper back.']}
};
'''
s=s.replace(needle,insert+needle,1)
old='''  dlg.innerHTML=`<div class="atlas-detail-top"><div><div class="exercise-index">ATLAS MOVEMENT LIBRARY</div><h2>${esc(name)}</h2></div><button type="button" class="icon-btn" data-detail-close aria-label="Close details">×</button></div><img class="atlas-detail-art" src="${exerciseArt(name)}" alt="Stylized ${esc(name)} movement study"><div class="atlas-detail-grid"><div><small>PRIMARY / SECONDARY</small><strong>${esc(muscles)}</strong></div><div><small>DEFAULT TARGET</small><strong>${range}</strong></div><div><small>EQUIPMENT</small><strong>${esc(meta?.equipment||'See exercise')}</strong></div></div><p class="atlas-detail-note">Illustration is a stylized movement reference, not a technical coaching diagram. Use a controlled range of motion and adjust setup to your equipment and comfort.</p>`;'''
new='''  const pilot=ATLAS_PILOT[name];
  const pilotArt=pilot?`./exercise-art/${pilot.art}-pilot.webp`:exerciseArt(name);
  const guide=pilot?`<div class="atlas-pilot-positions">${pilot.positions.map((t,i)=>`<div><small>${i?'FINISH':'START'}</small><span>${esc(t)}</span></div>`).join('')}</div><div class="atlas-pilot-cues"><small>TECHNIQUE & SETUP</small><ul>${pilot.cues.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>`:'';
  dlg.innerHTML=`<div class="atlas-detail-top"><div><div class="exercise-index">ATLAS MOVEMENT LIBRARY ${pilot?'· ILLUSTRATION PILOT':''}</div><h2>${esc(name)}</h2></div><button type="button" class="icon-btn" data-detail-close aria-label="Close details">×</button></div><img class="atlas-detail-art" src="${pilotArt}" alt="Vintage illustration of ${esc(name)}"><div class="atlas-detail-grid"><div><small>PRIMARY / SECONDARY</small><strong>${esc(muscles)}</strong></div><div><small>DEFAULT TARGET</small><strong>${range}</strong></div><div><small>EQUIPMENT</small><strong>${esc(meta?.equipment||'See exercise')}</strong></div></div>${guide}<p class="atlas-detail-note">${pilot?'Pilot illustration: visual reference only, not a verified coaching diagram. Follow qualified instruction and your equipment’s guidance.':'Illustration is a stylized movement reference, not a technical coaching diagram. Use a controlled range of motion and adjust setup to your equipment and comfort.'}</p>`;'''
if old not in s: raise Exception('dialog not found')
s=s.replace(old,new,1)
s=s.replace('<img src="${exerciseArt(ex[0])}" alt="${esc(ex[0])} movement illustration"','<img src="${ATLAS_PILOT[ex[0]]?`./exercise-art/${ATLAS_PILOT[ex[0]].art}-pilot.webp`:exerciseArt(ex[0])}" alt="${esc(ex[0])} movement illustration"',1)
f.write_text(s)
css=p/'styles.css'; css.write_text(css.read_text()+'''\n/* Atlas dual-illustration pilot */\n.atlas-pilot-positions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 0}\n.atlas-pilot-positions>div,.atlas-pilot-cues{background:#17222D;border:1px solid #56616D;border-radius:12px;padding:12px}\n.atlas-pilot-positions small,.atlas-pilot-cues small{display:block;color:#C59A59;font-size:11px;letter-spacing:.08em;font-weight:700;margin-bottom:6px}\n.atlas-pilot-positions span{display:block;color:#E8DCC7;font-size:12px;line-height:1.5}\n.atlas-pilot-cues ul{margin:7px 0 0;padding-left:20px;color:#E8DCC7;font-size:13px;line-height:1.65}\n''')
sw=p/'sw.js';ss=sw.read_text().replace('heldkraft-atlas-v28','heldkraft-atlas-v29-pilot');ss=ss.replace("'./icons/icon-192.png', './icons/icon-512.png',","'./icons/icon-192.png', './icons/icon-512.png',\n  './exercise-art/pec-deck-pilot.webp', './exercise-art/barbell-bench-press-pilot.webp', './exercise-art/barbell-back-squat-pilot.webp',")
sw.write_text(ss)
readme=p/'README.md';readme.write_text(readme.read_text()+'''\n\n## v29: Three-exercise dual-style illustration pilot\n\nPec Deck, Barbell Bench Press and Barbell Back Squat now use vintage illustrated thumbnails and larger detail views with text descriptions of start/finish positions and setup cues. Other exercises retain the v28 SVG illustrations. The three new images are **visual concept crops**, not independently verified anatomical instruction. This is an opt-in pilot for visual review; do not treat illustrations as technique coaching. The local data key is unchanged.\n''')
